INSERT INTO public.movies (title, description, poster_url, duration_minutes, genres, languages, certificate, rating, release_date, status, tmdb_id)
VALUES
  ('Finding Nemo', 'Nemo, an adventurous young clownfish, is unexpectedly taken from his Great Barrier Reef home to a dentist''s office aquarium. It''s up to his worrisome father Marlin and a friendly but forgetful fish Dory to bring Nemo home -- meeting vegetarian sharks, surfer dude turtles, hypnotic jellyfish, hungry seagulls, and more along the way.', 'https://image.tmdb.org/t/p/w500/syPWyeeqzTQIxjIUaIFI7d0TyEY.jpg', 100, ARRAY['Animation','Family'], ARRAY['English'], 'UA', 7.6, '2003-05-30', 'now_showing'::public.movie_status, 12),
  ('Big Hero 6', 'The special bond that develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.', 'https://image.tmdb.org/t/p/w500/9gLu47Zw5ertuFTZaxXOvNfy78T.jpg', 102, ARRAY['Adventure','Family','Animation','Action','Comedy'], ARRAY['English'], 'UA', 7.8, '2014-10-24', 'now_showing'::public.movie_status, 177572),
  ('Back to the Future', 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.', 'https://image.tmdb.org/t/p/w500/pTpxQB1N0waaSc3OSn0e9oc8kx9.jpg', 116, ARRAY['Adventure','Comedy','Science Fiction','Family'], ARRAY['English'], 'UA', 8.0, '1985-07-03', 'now_showing'::public.movie_status, 105),
  ('X-Men: Days of Future Past', 'The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.', 'https://image.tmdb.org/t/p/w500/giUK8ppRbfistadVzHtpainkhq4.jpg', 131, ARRAY['Action','Adventure','Fantasy','Science Fiction'], ARRAY['English'], 'UA', 7.5, '2014-05-15', 'now_showing'::public.movie_status, 127585),
  ('Monsters, Inc.', 'James Sullivan and Mike Wazowski are monsters, they earn their living scaring children and are the best in the business... even though they''re more afraid of the children than they are of them. When a child accidentally enters their world, James and Mike suddenly find that kids are not to be afraid of and they uncover a conspiracy that could threaten all children across the world.', 'https://image.tmdb.org/t/p/w500/93Y9BGx8blzmZOPSoivkFfaifqU.jpg', 92, ARRAY['Animation','Comedy','Family'], ARRAY['English'], 'UA', 7.5, '2001-11-01', 'now_showing'::public.movie_status, 585),
  ('Harry Potter and the Deathly Hallows: Part 2', 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort''s formidable skills.', 'https://image.tmdb.org/t/p/w500/fTplI1NCSuEDP4ITLcTps739fcC.jpg', 130, ARRAY['Family','Fantasy','Adventure'], ARRAY['English'], 'UA', 7.9, '2011-07-07', 'now_showing'::public.movie_status, 12445),
  ('Kingsman: The Secret Service', 'The story of a super-secret spy organization that recruits an unrefined but promising street kid into the agency''s ultra-competitive training program just as a global threat emerges from a twisted tech genius.', 'https://image.tmdb.org/t/p/w500/8x7ej0LnHdKUqilNNJXYOeyB6L9.jpg', 130, ARRAY['Crime','Comedy','Action','Adventure'], ARRAY['English'], 'UA', 7.6, '2015-01-29', 'now_showing'::public.movie_status, 207703),
  ('Lucy', 'A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.', 'https://image.tmdb.org/t/p/w500/rwn876MeqienhOVSSjtUPnwxn0Z.jpg', 89, ARRAY['Action','Science Fiction'], ARRAY['普通话','English'], 'UA', 6.3, '2014-07-14', 'now_showing'::public.movie_status, 240832),
  ('Harry Potter and the Prisoner of Azkaban', 'Harry, Ron and Hermione return to Hogwarts for another magic-filled year. Harry comes face to face with danger yet again, this time in the form of escaped convict, Sirius Black – and turns to sympathetic Professor Lupin for help.', 'https://image.tmdb.org/t/p/w500/jUFjMoLh8T2CWzHUSjKCojI5SHu.jpg', 141, ARRAY['Adventure','Fantasy','Family'], ARRAY['English'], 'UA', 7.7, '2004-05-31', 'now_showing'::public.movie_status, 673),
  ('Ant-Man', 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', 'https://image.tmdb.org/t/p/w500/D6e8RJf2qUstnfkTslTXNTUAlT.jpg', 117, ARRAY['Science Fiction','Action','Adventure'], ARRAY['English'], 'UA', 7.0, '2015-07-14', 'now_showing'::public.movie_status, 102899),
  ('The Godfather', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.', 'https://image.tmdb.org/t/p/w500/rPdtLWNsZmAtoZl9PK7S2wE3qiS.jpg', 175, ARRAY['Drama','Crime'], ARRAY['English','Italiano'], 'UA', 8.5, '1972-03-14', 'now_showing'::public.movie_status, 238),
  ('Gone Girl', 'With his wife''s disappearance having become the focus of an intense media circus, a man sees the spotlight turned on him when it''s suspected that he may not be innocent.', 'https://image.tmdb.org/t/p/w500/gdiLTof3rbPDAmPaCf4g6op46bj.jpg', 145, ARRAY['Mystery','Thriller','Drama'], ARRAY['English'], 'UA', 7.9, '2014-10-01', 'now_showing'::public.movie_status, 210577),
  ('The Empire Strikes Back', 'The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.', 'https://image.tmdb.org/t/p/w500/6u1fYtxG5eqjhtCPDx04pJphQRW.jpg', 124, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English'], 'UA', 8.2, '1980-05-17', 'now_showing'::public.movie_status, 1891),
  ('Harry Potter and the Chamber of Secrets', 'Ignoring threats to his life, Harry returns to Hogwarts to investigate – aided by Ron and Hermione – a mysterious series of attacks.', 'https://image.tmdb.org/t/p/w500/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg', 161, ARRAY['Adventure','Fantasy','Family'], ARRAY['English'], 'UA', 7.4, '2002-11-13', 'now_showing'::public.movie_status, 672),
  ('Se7en', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Sommerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.', 'https://image.tmdb.org/t/p/w500/8zw8IL4zEPjkh8Aysdcd0FwGMb0.jpg', 127, ARRAY['Crime','Mystery','Thriller'], ARRAY['English'], 'UA', 8.1, '1995-09-22', 'now_showing'::public.movie_status, 807),
  ('Life of Pi', 'The story of an Indian boy named Pi, a zookeeper''s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean.', 'https://image.tmdb.org/t/p/w500/sLYdcz7easaS7CmJGwQcVVYZqiF.jpg', 127, ARRAY['Adventure','Drama','Action'], ARRAY['English','Français'], 'UA', 7.2, '2012-11-20', 'now_showing'::public.movie_status, 87827),
  ('The Imitation Game', 'Based on the real life story of legendary cryptanalyst Alan Turing, the film portrays the nail-biting race against time by Turing and his brilliant team of code-breakers at Britain''s top-secret Government Code and Cypher School at Bletchley Park, during the darkest days of World War II.', 'https://image.tmdb.org/t/p/w500/noUp0XOqIcmgefRnRZa1nhtRvWO.jpg', 113, ARRAY['History','Drama','Thriller','War'], ARRAY['English'], 'UA', 8.0, '2014-11-14', 'now_showing'::public.movie_status, 205596),
  ('Sherlock Holmes', 'Eccentric consulting detective, Sherlock Holmes and Doctor John Watson battle to bring down a new nemesis and unravel a deadly plot that could destroy England.', 'https://image.tmdb.org/t/p/w500/22ngurXbLqab7Sko6aTSdwOCe5W.jpg', 128, ARRAY['Action','Adventure','Crime','Mystery'], ARRAY['English','Français'], 'UA', 7.0, '2009-12-23', 'now_showing'::public.movie_status, 10528),
  ('Captain America: The Winter Soldier', 'After the cataclysmic events in New York with The Avengers, Steve Rogers, aka Captain America is living quietly in Washington, D.C. and trying to adjust to the modern world. But when a S.H.I.E.L.D. colleague comes under attack, Steve becomes embroiled in a web of intrigue that threatens to put the world at risk. Joining forces with the Black Widow, Captain America struggles to expose the ever-widening conspiracy while fighting off professional assassins sent to silence him at every turn. When the full scope of the villainous plot is revealed, Captain America and the Black Widow enlist the help of a new ally, the Falcon. However, they soon find themselves up against an unexpected and formidable enemy—the Winter Soldier.', 'https://image.tmdb.org/t/p/w500/5TQ6YDmymBpnF005OyoB7ohZps9.jpg', 136, ARRAY['Action','Adventure','Science Fiction'], ARRAY['English'], 'UA', 7.6, '2014-03-20', 'now_showing'::public.movie_status, 100402),
  ('Doctor Strange', 'After his career is destroyed, a brilliant but arrogant surgeon gets a new lease on life when a sorcerer takes him under his wing and trains him to defend the world against evil.', 'https://image.tmdb.org/t/p/w500/4PiiNGXj1KENTmCBHeN6Mskj2Fq.jpg', 115, ARRAY['Action','Adventure','Fantasy','Science Fiction'], ARRAY['English'], 'UA', 7.1, '2016-10-25', 'now_showing'::public.movie_status, 284052),
  ('Gravity', 'Dr. Ryan Stone, a brilliant medical engineer on her first Shuttle mission, with veteran astronaut Matt Kowalsky in command of his last flight before retiring. But on a seemingly routine spacewalk, disaster strikes. The Shuttle is destroyed, leaving Stone and Kowalsky completely alone-tethered to nothing but each other and spiraling out into the blackness of space. The deafening silence tells them they have lost any link to Earth and any chance for rescue. As fear turns to panic, every gulp of air eats away at what little oxygen is left. But the only way home may be to go further out into the terrifying expanse of space.', 'https://image.tmdb.org/t/p/w500/uPxtxhB2Fy9ihVqtBtNGHmknJqV.jpg', 91, ARRAY['Science Fiction','Thriller','Drama'], ARRAY['English'], 'UA', 7.3, '2013-09-27', 'now_showing'::public.movie_status, 49047),
  ('The Hunger Games: Mockingjay - Part 1', 'Katniss Everdeen reluctantly becomes the symbol of a mass rebellion against the autocratic Capitol.', 'https://image.tmdb.org/t/p/w500/gj282Pniaa78ZJfbaixyLXnXEDI.jpg', 123, ARRAY['Science Fiction','Adventure','Thriller'], ARRAY['English'], 'UA', 6.6, '2014-11-18', 'now_showing'::public.movie_status, 131631),
  ('Harry Potter and the Goblet of Fire', 'Harry starts his fourth year at Hogwarts, competes in the treacherous Triwizard Tournament and faces the evil Lord Voldemort. Ron and Hermione help Harry manage the pressure – but Voldemort lurks, awaiting his chance to destroy Harry and all that he stands for.', 'https://image.tmdb.org/t/p/w500/6sASqcdrEHXxUhA3nFpjrRecPD2.jpg', 157, ARRAY['Adventure','Fantasy','Family'], ARRAY['English','Français'], 'UA', 7.5, '2005-11-05', 'now_showing'::public.movie_status, 674),
  ('Arrival', 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.', 'https://image.tmdb.org/t/p/w500/hLudzvGfpi6JlwUnsNhXwKKg4j.jpg', 113, ARRAY['Thriller','Drama','Science Fiction','Mystery'], ARRAY['普通话','English'], 'UA', 7.2, '2016-11-10', 'now_showing'::public.movie_status, 329865),
  ('Harry Potter and the Deathly Hallows: Part 1', 'Harry, Ron and Hermione walk away from their last year at Hogwarts to find and destroy the remaining Horcruxes, putting an end to Voldemort''s bid for immortality. But with Harry''s beloved Dumbledore dead and Voldemort''s unscrupulous Death Eaters on the loose, the world is more dangerous than ever.', 'https://image.tmdb.org/t/p/w500/maP4MTfPCeVD2FZbKTLUgriOW4R.jpg', 146, ARRAY['Adventure','Fantasy','Family'], ARRAY['English'], 'UA', 7.5, '2010-10-17', 'now_showing'::public.movie_status, 12444),
  ('World War Z', 'Life for former United Nations investigator Gerry Lane and his family seems content. Suddenly, the world is plagued by a mysterious infection turning whole human populations into rampaging mindless zombies. After barely escaping the chaos, Lane is persuaded to go on a mission to investigate this disease. What follows is a perilous trek around the world where Lane must brave horrific dangers and long odds to find answers before human civilization falls.', 'https://image.tmdb.org/t/p/w500/Ha5t0J21eyiq6Az1EXzx0iwsGH.jpg', 116, ARRAY['Action','Drama','Horror','Science Fiction','Thriller'], ARRAY['English'], 'UA', 6.7, '2013-06-20', 'now_showing'::public.movie_status, 72190),
  ('Now You See Me', 'An FBI agent and an Interpol detective track a team of illusionists who pull off bank heists during their performances and reward their audiences with the money.', 'https://image.tmdb.org/t/p/w500/A06e9YJ5ry3WXEIFIAD1mKBxcuZ.jpg', 115, ARRAY['Thriller','Crime'], ARRAY['Français','English'], 'UA', 7.3, '2013-05-29', 'now_showing'::public.movie_status, 75656),
  ('Harry Potter and the Order of the Phoenix', 'Returning for his fifth year of study at Hogwarts, Harry is stunned to find that his warnings about the return of Lord Voldemort have been ignored. Left with no choice, Harry takes matters into his own hands, training a small group of students – dubbed ''Dumbledore''s Army'' – to defend themselves against the dark arts.', 'https://image.tmdb.org/t/p/w500/4YnLxYLHhT4UQ8i9jxAXWy46Xuw.jpg', 138, ARRAY['Adventure','Fantasy','Family','Mystery'], ARRAY['English'], 'UA', 7.4, '2007-06-28', 'now_showing'::public.movie_status, 675),
  ('Fantastic Beasts and Where to Find Them', 'In 1926, Newt Scamander arrives at the Magical Congress of the United States of America with a magically expanded briefcase, which houses a number of dangerous creatures and their habitats. When the creatures escape from the briefcase, it sends the American wizarding authorities after Newt, and threatens to strain even further the state of magical and non-magical relations.', 'https://image.tmdb.org/t/p/w500/gri0DDxsERr6B2sOR1fGLxLpSLx.jpg', 133, ARRAY['Adventure','Family','Fantasy'], ARRAY['English'], 'UA', 7.2, '2016-11-16', 'now_showing'::public.movie_status, 259316),
  ('Gladiator', 'In the year 180, the death of emperor Marcus Aurelius throws the Roman Empire into chaos. Maximus is one of the Roman army''s most capable and trusted generals and a key advisor to the emperor. As Marcus'' devious son Commodus ascends to the throne, Maximus is set to be executed. He escapes, but is captured by slave traders. Renamed Spaniard and forced to become a gladiator, Maximus must battle to the death with other men for the amusement of paying audiences. His battle skills serve him well, and he becomes one of the most famous and admired men to fight in the Colosseum. Determined to avenge himself against the man who took away his freedom and laid waste to his family, Maximus believes that he can use his fame and skill in the ring to avenge the loss of his family and former glory. As the gladiator begins to challenge his rule, Commodus decides to put his own fighting mettle to the test by squaring off with Maximus in a battle to the death.', 'https://image.tmdb.org/t/p/w500/6WBIzCgmDCYrqh64yDREGeDk9d3.jpg', 155, ARRAY['Action','Drama','Adventure'], ARRAY['English'], 'UA', 7.9, '2000-05-01', 'now_showing'::public.movie_status, 98),
  ('The Maze Runner', 'Set in a post-apocalyptic world, young Thomas is deposited in a community of boys after his memory is erased, soon learning they''re all trapped in a maze that will require him to join forces with fellow "runners" for a shot at escape.', 'https://image.tmdb.org/t/p/w500/coss7RgL0NH6g4fC2s5atvf3dFO.jpg', 113, ARRAY['Action','Mystery','Science Fiction','Thriller'], ARRAY['English'], 'UA', 7.0, '2014-09-10', 'now_showing'::public.movie_status, 198663),
  ('Beauty and the Beast', 'A live-action adaptation of Disney''s version of the classic ''Beauty and the Beast'' tale of a cursed prince and a beautiful young woman who helps him break the spell.', 'https://image.tmdb.org/t/p/w500/tWqifoYuwLETmmasnGHO7xBjEtt.jpg', 129, ARRAY['Family','Fantasy','Romance'], ARRAY['English'], 'UA', 6.8, '2017-03-16', 'now_showing'::public.movie_status, 321612),
  ('The Lion King', 'A young lion cub named Simba can''t wait to be king. But his uncle craves the title for himself and will stop at nothing to get it.', 'https://image.tmdb.org/t/p/w500/bKPtXn9n4M4s8vvZrbw40mYsefB.jpg', 89, ARRAY['Family','Animation','Drama'], ARRAY['English'], 'UA', 8.0, '1994-06-23', 'now_showing'::public.movie_status, 8587),
  ('John Wick', 'Ex-lunatic John Wick comes off his meds to track down the bounders that killed his dog and made off with his self-respect', 'https://image.tmdb.org/t/p/w500/5vHssUeVe25bMrof1HyaPyWgaP.jpg', 101, ARRAY['Action','Thriller'], ARRAY['Magyar','English'], 'UA', 7.0, '2014-10-22', 'now_showing'::public.movie_status, 245891),
  ('Frozen', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', 'https://image.tmdb.org/t/p/w500/jIjdFXKUNtdf1bwqMrhearpyjMj.jpg', 102, ARRAY['Animation','Adventure','Family'], ARRAY['English'], 'UA', 7.3, '2013-11-27', 'now_showing'::public.movie_status, 109445),
  ('Harry Potter and the Half-Blood Prince', 'As Harry begins his sixth year at Hogwarts, he discovers an old book marked as ''Property of the Half-Blood Prince'', and begins to learn more about Lord Voldemort''s dark past.', 'https://image.tmdb.org/t/p/w500/bFXys2nhALwDvpkF3dP3Vvdfn8b.jpg', 153, ARRAY['Adventure','Fantasy','Family'], ARRAY['English'], 'UA', 7.4, '2009-07-07', 'now_showing'::public.movie_status, 767),
  ('Toy Story', 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.', 'https://image.tmdb.org/t/p/w500/rhIRbceoE9lR4veEXuwCC2wARtG.jpg', 81, ARRAY['Animation','Comedy','Family'], ARRAY['English'], 'UA', 7.7, '1995-10-30', 'now_showing'::public.movie_status, 862),
  ('The Intouchables', 'A true story of two men who should never have met – a quadriplegic aristocrat who was injured in a paragliding accident and a young man from the projects.', 'https://image.tmdb.org/t/p/w500/4mFsNQwbD0F237Tx7gAPotd0nbJ.jpg', 112, ARRAY['Drama','Comedy'], ARRAY['English','Français'], 'UA', 8.2, '2011-11-02', 'now_showing'::public.movie_status, 77338),
  ('Spider-Man', 'After being bitten by a genetically altered spider, nerdy high school student Peter Parker is endowed with amazing powers.', 'https://image.tmdb.org/t/p/w500/rZd0y1X1Gw4t5B3f01Qzj8DYY66.jpg', 121, ARRAY['Fantasy','Action'], ARRAY['English'], 'UA', 6.8, '2002-05-01', 'now_showing'::public.movie_status, 557),
  ('Pirates of the Caribbean: Dead Man''s Chest', 'Captain Jack Sparrow works his way out of a blood debt with the ghostly Davey Jones, he also attempts to avoid eternal damnation.', 'https://image.tmdb.org/t/p/w500/waFr5RVKaQ9dzOt3nQuIVB1FiPu.jpg', 151, ARRAY['Adventure','Fantasy','Action'], ARRAY['English','Türkçe'], 'UA', 7.0, '2006-06-20', 'now_showing'::public.movie_status, 58),
  ('The Incredibles', 'Bob Parr has given up his superhero days to log in time as an insurance adjuster and raise his three children with his formerly heroic wife in suburbia. But when he receives a mysterious assignment, it''s time to get back into costume.', 'https://image.tmdb.org/t/p/w500/huGDgQRB24IzkJLNqe5zq1pdvEE.jpg', 115, ARRAY['Action','Adventure','Animation','Family'], ARRAY['Français','English'], 'UA', 7.4, '2004-11-05', 'now_showing'::public.movie_status, 9806),
  ('Fast & Furious 6', 'Hobbs has Dominic and Brian reassemble their crew to take down a team of mercenaries: Dominic unexpectedly gets convoluted also facing his presumed deceased girlfriend, Letty.', 'https://image.tmdb.org/t/p/w500/b9gTJKLdSbwcQRKzmqMq3dMfRwI.jpg', 130, ARRAY['Action','Thriller','Crime'], ARRAY['English','Pусский'], 'UA', 6.7, '2013-05-06', 'now_showing'::public.movie_status, 82992),
  ('X-Men: First Class', 'Before Charles Xavier and Erik Lensherr took the names Professor X and Magneto, they were two young men discovering their powers for the first time. Before they were arch-enemies, they were closest of friends, working together with other mutants (some familiar, some new), to stop the greatest threat the world has ever known.', 'https://image.tmdb.org/t/p/w500/7SSm7BfzFoVzmd6fCDccj7qRxc8.jpg', 132, ARRAY['Action','Science Fiction','Adventure'], ARRAY['Deutsch','English'], 'UA', 7.1, '2011-05-24', 'now_showing'::public.movie_status, 49538),
  ('Prometheus', 'A team of explorers discover a clue to the origins of mankind on Earth, leading them on a journey to the darkest corners of the universe. There, they must fight a terrifying battle to save the future of the human race.', 'https://image.tmdb.org/t/p/w500/ng8ALjSDhUmwLl7vtjUWIZNQSlt.jpg', 124, ARRAY['Science Fiction','Adventure','Mystery'], ARRAY['English'], 'UA', 6.3, '2012-05-30', 'now_showing'::public.movie_status, 70981),
  ('Saving Private Ryan', 'As U.S. troops storm the beaches of Normandy, three brothers lie dead on the battlefield, with a fourth trapped behind enemy lines. Ranger captain John Miller and seven men are tasked with penetrating German-held territory and bringing the boy home.', 'https://image.tmdb.org/t/p/w500/miDoEMlYDJhOCvxlzI0wZqBs9Yt.jpg', 169, ARRAY['Drama','History','War'], ARRAY['Český','Deutsch'], 'UA', 7.9, '1998-07-24', 'now_showing'::public.movie_status, 857),
  ('Rogue One: A Star Wars Story', 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.', 'https://image.tmdb.org/t/p/w500/qjiskwlV1qQzRCjpV0cL9pEMF9a.jpg', 133, ARRAY['Action','Adventure','Science Fiction'], ARRAY['English'], 'UA', 7.4, '2016-12-14', 'now_showing'::public.movie_status, 330459),
  ('300', 'Based on Frank Miller''s graphic novel, "300" is very loosely based the 480 B.C. Battle of Thermopylae, where the King of Sparta led his army against the advancing Persians; the battle is said to have inspired all of Greece to band together against the Persians, and helped usher in the world''s first democracy.', 'https://image.tmdb.org/t/p/w500/bYR8O1H1ZlME7Dm9ysfTYZnRDpw.jpg', 117, ARRAY['Action','Adventure','War'], ARRAY['English'], 'UA', 7.0, '2006-12-09', 'now_showing'::public.movie_status, 1271),
  ('Kill Bill: Vol. 1', 'An assassin is shot at the altar by her ruthless employer, Bill and other members of their assassination circle – but ''The Bride'' lives to plot her vengeance. Setting out for some payback, she makes a death list and hunts down those who wronged her, saving Bill for last.', 'https://image.tmdb.org/t/p/w500/97fNAi62HawGjWru7PvVmF7RAbU.jpg', 111, ARRAY['Action','Crime'], ARRAY['English','日本語'], 'UA', 7.7, '2003-10-10', 'now_showing'::public.movie_status, 24),
  ('Pirates of the Caribbean: On Stranger Tides', 'Captain Jack Sparrow crosses paths with a woman from his past, and he''s not sure if it''s love -- or if she''s a ruthless con artist who''s using him to find the fabled Fountain of Youth. When she forces him aboard the Queen Anne''s Revenge, the ship of the formidable pirate Blackbeard, Jack finds himself on an unexpected adventure in which he doesn''t know who to fear more: Blackbeard or the woman from his past.', 'https://image.tmdb.org/t/p/w500/wNUDAq5OUMOtxMlz64YaCp7gZma.jpg', 136, ARRAY['Adventure','Action','Fantasy'], ARRAY['English','Español'], 'UA', 6.4, '2011-05-14', 'now_showing'::public.movie_status, 1865),
  ('Wonder Woman', 'An Amazon princess comes to the world of Man to become the greatest of the female superheroes.', 'https://image.tmdb.org/t/p/w500/imekS7f1OuHyUP2LAiTEM0zBzUz.jpg', 141, ARRAY['Action','Adventure','Fantasy'], ARRAY['Deutsch','English'], 'UA', 7.2, '2017-05-30', 'now_showing'::public.movie_status, 297762),
  ('2012', 'Dr. Adrian Helmsley, part of a worldwide geophysical team investigating the effect on the earth of radiation from unprecedented solar storms, learns that the earth''s core is heating up. He warns U.S. President Thomas Wilson that the crust of the earth is becoming unstable and that without proper preparations for saving a fraction of the world''s population, the entire race is doomed. Meanwhile, writer Jackson Curtis stumbles on the same information. While the world''s leaders race to build "arks" to escape the impending cataclysm, Curtis struggles to find a way to save his family. Meanwhile, volcanic eruptions and earthquakes of unprecedented strength wreak havoc around the world.', 'https://image.tmdb.org/t/p/w500/5tIW9nTuxxy8iXSvsKJqFDVZpyg.jpg', 158, ARRAY['Action','Adventure','Science Fiction'], ARRAY['English','Français'], 'UA', 5.6, '2009-10-10', 'now_showing'::public.movie_status, 14161),
  ('Edge of Tomorrow', 'Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.', 'https://image.tmdb.org/t/p/w500/tpoVEYvm6qcXueZrQYJNRLXL88s.jpg', 113, ARRAY['Action','Science Fiction'], ARRAY['English'], 'UA', 7.6, '2014-05-27', 'now_showing'::public.movie_status, 137113),
  ('I Am Legend', 'Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.', 'https://image.tmdb.org/t/p/w500/6OA0I8hhW9zftWoCYxJAzXW9UIN.jpg', 101, ARRAY['Drama','Horror','Action','Thriller','Science Fiction'], ARRAY['English'], 'UA', 6.9, '2007-12-14', 'now_showing'::public.movie_status, 6479),
  ('Zootopia', 'Determined to prove herself, Officer Judy Hopps, the first bunny on Zootopia''s police force, jumps at the chance to crack her first case - even if it means partnering with scam-artist fox Nick Wilde to solve the mystery.', 'https://image.tmdb.org/t/p/w500/sM33SANp9z6rXW8Itn7NnG1GOEs.jpg', 108, ARRAY['Animation','Adventure','Family','Comedy'], ARRAY['English'], 'UA', 7.7, '2016-02-11', 'now_showing'::public.movie_status, 269149),
  ('Jurassic Park', 'A wealthy entrepreneur secretly creates a theme park featuring living dinosaurs drawn from prehistoric DNA. Before opening day, he invites a team of experts and his two eager grandchildren to experience the park and help calm anxious investors. However, the park is anything but amusing as the security systems go off-line and the dinosaurs escape.', 'https://image.tmdb.org/t/p/w500/c414cDeQ9b6qLPLeKmiJuLDUREJ.jpg', 127, ARRAY['Adventure','Science Fiction'], ARRAY['English','Español'], 'UA', 7.6, '1993-06-11', 'now_showing'::public.movie_status, 329),
  ('Pacific Rim', 'When legions of monstrous creatures, known as Kaiju, started rising from the sea, a war began that would take millions of lives and consume humanity''s resources for years on end. To combat the giant Kaiju, a special type of weapon was devised: massive robots, called Jaegers, which are controlled simultaneously by two pilots whose minds are locked in a neural bridge. But even the Jaegers are proving nearly defenseless in the face of the relentless Kaiju. On the verge of defeat, the forces defending mankind have no choice but to turn to two unlikely heroes—a washed-up former pilot (Charlie Hunnam) and an untested trainee (Rinko Kikuchi)—who are teamed to drive a legendary but seemingly obsolete Jaeger from the past. Together, they stand as mankind''s last hope against the mounting apocalypse.', 'https://image.tmdb.org/t/p/w500/sCJEwEShZvruTpQ2a4yiX3Q9EyZ.jpg', 131, ARRAY['Action','Science Fiction','Adventure'], ARRAY['English'], 'UA', 6.7, '2013-07-11', 'now_showing'::public.movie_status, 68726),
  ('The Hobbit: The Battle of the Five Armies', 'Immediately after the events of The Desolation of Smaug, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.', 'https://image.tmdb.org/t/p/w500/9zRzFJuaj0CHIOhAkcCcFTvyu2X.jpg', 144, ARRAY['Action','Adventure','Fantasy'], ARRAY['English'], 'UA', 7.1, '2014-12-10', 'now_showing'::public.movie_status, 122917),
  ('Thor: The Dark World', 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.', 'https://image.tmdb.org/t/p/w500/bnX5PqAdQZRXSw3aX3DutDcdso5.jpg', 112, ARRAY['Action','Adventure','Fantasy'], ARRAY['English'], 'UA', 6.8, '2013-10-29', 'now_showing'::public.movie_status, 76338),
  ('Oblivion', 'Jack Harper is one of the last few drone repairmen stationed on Earth.  Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete.  His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft.  Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', 'https://image.tmdb.org/t/p/w500/hmOzkHlkGvi8x24fYpFSnXvjklv.jpg', 124, ARRAY['Action','Science Fiction','Adventure','Mystery'], ARRAY['English'], 'UA', 6.4, '2013-04-10', 'now_showing'::public.movie_status, 75612),
  ('Ex Machina', 'Caleb, a 26 year old coder at the world''s largest internet company, wins a competition to spend a week at a private mountain retreat belonging to Nathan, the reclusive CEO of the company. But when Caleb arrives at the remote location he finds that he will have to participate in a strange and fascinating experiment in which he must interact with the world''s first true artificial intelligence, housed in the body of a beautiful robot girl.', 'https://image.tmdb.org/t/p/w500/btbRB7BrD887j5NrvjxceRDmaot.jpg', 108, ARRAY['Drama','Science Fiction'], ARRAY['English'], 'UA', 7.6, '2015-01-21', 'now_showing'::public.movie_status, 264660),
  ('Guardians of the Galaxy Vol. 2', 'The Guardians must fight to keep their newfound family together as they unravel the mysteries of Peter Quill''s true parentage.', 'https://image.tmdb.org/t/p/w500/y4MBh0EjBlMuOzv9axM4qJlmhzz.jpg', 137, ARRAY['Action','Adventure','Comedy','Science Fiction'], ARRAY['English'], 'UA', 7.6, '2017-04-19', 'now_showing'::public.movie_status, 283995),
  ('Silver Linings Playbook', 'After spending eight months in a mental institution, a former teacher moves back in with his parents and tries to reconcile with his ex-wife.', 'https://image.tmdb.org/t/p/w500/ilrZAV2klTB0FLxLb01bOp5pzD9.jpg', 122, ARRAY['Drama','Comedy','Romance'], ARRAY['English'], 'UA', 7.0, '2012-09-08', 'now_showing'::public.movie_status, 82693),
  ('X-Men: Apocalypse', 'After the re-emergence of the world''s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.', 'https://image.tmdb.org/t/p/w500/zSouWWrySXshPCT4t3UKCQGayyo.jpg', 144, ARRAY['Science Fiction'], ARRAY['English'], 'UA', 6.4, '2016-05-18', 'now_showing'::public.movie_status, 246655),
  ('Ted', 'John Bennett, a man whose childhood wish of bringing his teddy bear to life came true, now must decide between keeping the relationship with the bear or his girlfriend, Lori.', 'https://image.tmdb.org/t/p/w500/yLdP2vDa1BqxLSbikGypGtAEOGe.jpg', 106, ARRAY['Comedy','Fantasy'], ARRAY['English'], 'UA', 6.3, '2012-06-29', 'now_showing'::public.movie_status, 72105),
  ('Divergent', 'In a world divided into factions based on personality types, Tris learns that she''s been classified as Divergent and won''t fit in. When she discovers a plot to destroy Divergents, Tris and the mysterious Four must find out what makes Divergents dangerous before it''s too late.', 'https://image.tmdb.org/t/p/w500/yTtx2ciqk4XdN1oKhMMDy3f5ue3.jpg', 139, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English'], 'UA', 6.9, '2014-03-14', 'now_showing'::public.movie_status, 157350),
  ('Looper', 'In the futuristic action thriller Looper, time travel will be invented but it will be illegal and only available on the black market. When the mob wants to get rid of someone, they will send their target 30 years into the past where a looper, a hired gun, like Joe is waiting to mop up. Joe is getting rich and life is good until the day the mob decides to close the loop, sending back Joe''s future self for assassination.', 'https://image.tmdb.org/t/p/w500/o4qXZMrZlfuTfwwNGMyTcx6p2uO.jpg', 118, ARRAY['Action','Thriller','Science Fiction'], ARRAY['English'], 'UA', 6.6, '2012-09-26', 'now_showing'::public.movie_status, 59967),
  ('Alice in Wonderland', 'Alice, an unpretentious and individual 19-year-old, is betrothed to a dunce of an English nobleman. At her engagement party, she escapes the crowd to consider whether to go through with the marriage and falls down a hole in the garden after spotting an unusual rabbit. Arriving in a strange and surreal place called ''Underland,'' she finds herself in a world that resembles the nightmares she had as a child, filled with talking animals, villainous queens and knights, and frumious bandersnatches. Alice realizes that she is there for a reason – to conquer the horrific Jabberwocky and restore the rightful queen to her throne.', 'https://image.tmdb.org/t/p/w500/pvEE5EN5N1yjmHmldfL4aJWm56l.jpg', 108, ARRAY['Family','Fantasy','Adventure'], ARRAY['English'], 'UA', 6.4, '2010-03-03', 'now_showing'::public.movie_status, 12155),
  ('Return of the Jedi', 'As Rebel leaders map their strategy for an all-out attack on the Emperor''s newer, bigger Death Star. Han Solo remains frozen in the cavernous desert fortress of Jabba the Hutt, the most loathsome outlaw in the universe, who is also keeping Princess Leia as a slave girl. Now a master of the Force, Luke Skywalker rescues his friends, but he cannot become a true Jedi Knight until he wages his own crucial battle against Darth Vader, who has sworn to win Luke over to the dark side of the Force.', 'https://image.tmdb.org/t/p/w500/jx5p0aHlbPXqe3AH9G15NvmWaqQ.jpg', 135, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English'], 'UA', 7.9, '1983-05-23', 'now_showing'::public.movie_status, 1892),
  ('Brave', 'Brave is set in the mystical Scottish Highlands, where Mérida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Mérida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Mérida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Mérida’s quest — and serving as comic relief — are the kingdom’s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', 'https://image.tmdb.org/t/p/w500/qhABv2d4NZLhsOOA4iBFM4rfuJC.jpg', 93, ARRAY['Animation','Adventure','Comedy','Family','Action','Fantasy'], ARRAY['English'], 'UA', 6.7, '2012-06-21', 'now_showing'::public.movie_status, 62177),
  ('Kick-Ass', 'Dave Lizewski is an unnoticed high school student and comic book fan who one day decides to become a super-hero, even though he has no powers, training or meaningful reason to do so.', 'https://image.tmdb.org/t/p/w500/yZFrniO6qSwjTCosStXweYtczGT.jpg', 117, ARRAY['Action','Crime'], ARRAY['English'], 'UA', 7.1, '2010-03-22', 'now_showing'::public.movie_status, 23483),
  ('La La Land', 'Mia, an aspiring actress, serves lattes to movie stars in between auditions and Sebastian, a jazz musician, scrapes by playing cocktail party gigs in dingy bars, but as success mounts they are faced with decisions that begin to fray the fragile fabric of their love affair, and the dreams they worked so hard to maintain in each other threaten to rip them apart.', 'https://image.tmdb.org/t/p/w500/ylXCdC106IKiarftHkcacasaAcb.jpg', 128, ARRAY['Comedy','Drama','Music','Romance'], ARRAY['English'], 'UA', 7.9, '2016-11-29', 'now_showing'::public.movie_status, 313369),
  ('Despicable Me 2', 'Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal.', 'https://image.tmdb.org/t/p/w500/kQrYyZQHkwkUg2KlUDyvymj9FAp.jpg', 98, ARRAY['Animation','Comedy','Family'], ARRAY['English'], 'UA', 7.0, '2013-06-25', 'now_showing'::public.movie_status, 93456),
  ('Minions', 'Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.', 'https://image.tmdb.org/t/p/w500/q0R4crx2SehcEEQEkYObktdeFy.jpg', 91, ARRAY['Family','Animation','Adventure','Comedy'], ARRAY['English'], 'UA', 6.4, '2015-06-17', 'now_showing'::public.movie_status, 211672),
  ('Toy Story 3', 'Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.', 'https://image.tmdb.org/t/p/w500/mMltbSxwEdNE4Cv8QYLpzkHWTDo.jpg', 103, ARRAY['Animation','Family','Comedy'], ARRAY['English','Español'], 'UA', 7.6, '2010-06-16', 'now_showing'::public.movie_status, 10193),
  ('The Truman Show', 'Truman Burbank is the star of "The Truman Show", a 24-hour-a-day "reality" TV show that broadcasts every aspect of his life -- live and in color -- without his knowledge. His entire life has been an unending soap opera for consumption by the rest of the world. And everyone he knows -- including his wife and his best friend -- is really an actor, paid to be part of his life.', 'https://image.tmdb.org/t/p/w500/EelZzudHRvJmjWccWscN1S5vmI.jpg', 103, ARRAY['Comedy','Drama'], ARRAY['English'], 'UA', 7.8, '1998-06-04', 'now_showing'::public.movie_status, 37165),
  ('Birdman', 'A fading actor best known for his portrayal of a popular superhero attempts to mount a comeback by appearing in a Broadway play. As opening night approaches, his attempts to become more altruistic, rebuild his career, and reconnect with friends and family prove more difficult than expected.', 'https://image.tmdb.org/t/p/w500/rSZs93P0LLxqlVEbI001UKoeCQC.jpg', 119, ARRAY['Drama','Comedy'], ARRAY['English'], 'UA', 7.4, '2014-08-27', 'now_showing'::public.movie_status, 194662),
  ('Wreck-It Ralph', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', 'https://image.tmdb.org/t/p/w500/93FsllrXXWncp7BQYTdOU1XMRXo.jpg', 108, ARRAY['Family','Animation','Comedy','Adventure'], ARRAY['English'], 'UA', 7.1, '2012-11-01', 'now_showing'::public.movie_status, 82690),
  ('The Grand Budapest Hotel', 'The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.', 'https://image.tmdb.org/t/p/w500/nX5XotM9yprCKarRH4fzOq1VM1J.jpg', 99, ARRAY['Comedy','Drama'], ARRAY['English','Français'], 'UA', 8.0, '2014-02-26', 'now_showing'::public.movie_status, 120467),
  ('The Hobbit: The Desolation of Smaug', 'The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.', 'https://image.tmdb.org/t/p/w500/gQCiuxGsfiXH1su6lp9n0nd0UeH.jpg', 161, ARRAY['Adventure','Fantasy'], ARRAY['English'], 'UA', 7.6, '2013-12-11', 'now_showing'::public.movie_status, 57158),
  ('Pirates of the Caribbean: At World''s End', 'Captain Barbossa, long believed to be dead, has come back to life and is headed to the edge of the Earth with Will Turner and Elizabeth Swann. But nothing is quite as it seems.', 'https://image.tmdb.org/t/p/w500/bXb00CkHqx7TPchTGG131sWV59y.jpg', 169, ARRAY['Adventure','Fantasy','Action'], ARRAY['English'], 'UA', 6.9, '2007-05-19', 'now_showing'::public.movie_status, 285),
  ('Maleficent', 'The untold story of Disney''s most iconic villain from the 1959 classic ''Sleeping Beauty''. A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land.  Maleficent rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom - and to Maleficent''s true happiness as well.', 'https://image.tmdb.org/t/p/w500/4FYu1AAu14tuBU0lns0hbKiHUcH.jpg', 97, ARRAY['Fantasy','Adventure','Action','Family','Romance'], ARRAY['English'], 'UA', 7.0, '2014-05-28', 'now_showing'::public.movie_status, 102651),
  ('American Sniper', 'U.S. Navy SEAL Chris Kyle takes his sole mission—protect his comrades—to heart and becomes one of the most lethal snipers in American history. His pinpoint accuracy not only saves countless lives but also makes him a prime target of insurgents. Despite grave danger and his struggle to be a good husband and father to his family back in the States, Kyle serves four tours of duty in Iraq. However, when he finally returns home, he finds that he cannot leave the war behind.', 'https://image.tmdb.org/t/p/w500/svPHnYE7N5NAGO49dBmRhq0vDQ3.jpg', 133, ARRAY['War','Action'], ARRAY['English'], 'UA', 7.4, '2014-12-11', 'now_showing'::public.movie_status, 190859),
  ('Star Trek', 'The fate of the galaxy rests in the hands of bitter rivals. One, James Kirk, is a delinquent, thrill-seeking Iowa farm boy. The other, Spock, a Vulcan, was raised in a logic-based society that rejects all emotion. As fiery instinct clashes with calm reason, their unlikely but powerful partnership is the only thing capable of leading their crew through unimaginable danger, boldly going where no one has gone before. The human adventure has begun again.', 'https://image.tmdb.org/t/p/w500/6V0CY7pwdDOCDS2XqNWahmIlVYh.jpg', 127, ARRAY['Science Fiction','Action','Adventure'], ARRAY['English'], 'UA', 7.4, '2009-05-06', 'now_showing'::public.movie_status, 13475),
  ('Alien', 'During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.', 'https://image.tmdb.org/t/p/w500/2h00HrZs89SL3tXB4nbkiM7BKHs.jpg', 117, ARRAY['Horror','Action','Thriller','Science Fiction'], ARRAY['English','Español'], 'UA', 7.9, '1979-05-25', 'now_showing'::public.movie_status, 348),
  ('V for Vendetta', 'In a world in which Great Britain has become a fascist state, a masked vigilante known only as ''V'' conducts guerrilla warfare against the oppressive British government. When ''V'' rescues a young woman from the secret police, he finds in her an ally with whom he can continue his fight to free the people of Britain.', 'https://image.tmdb.org/t/p/w500/AoGpqw4S4ZGgwhlM3FgzFVwyIGl.jpg', 132, ARRAY['Action','Thriller','Fantasy'], ARRAY['English'], 'UA', 7.7, '2006-03-15', 'now_showing'::public.movie_status, 752),
  ('Black Swan', 'A ballet dancer wins the lead in "Swan Lake" and is perfect for the role of the delicate White Swan - Princess Odette - but slowly loses her mind as she becomes more and more like Odile, the Black Swan.', 'https://image.tmdb.org/t/p/w500/dQ7uxvsVTspVIsqjfgQj8usJpwX.jpg', 108, ARRAY['Drama','Thriller'], ARRAY['English','Français'], 'UA', 7.3, '2010-12-02', 'now_showing'::public.movie_status, 44214),
  ('Spectre', 'A cryptic message from Bond’s past sends him on a trail to uncover a sinister organization. While M battles political forces to keep the secret service alive, Bond peels back the layers of deceit to reveal the terrible truth behind SPECTRE.', 'https://image.tmdb.org/t/p/w500/hE24GYddaxB9MVZl1CaiI86M3kp.jpg', 148, ARRAY['Action','Adventure','Crime'], ARRAY['Français','English'], 'UA', 6.3, '2015-10-26', 'now_showing'::public.movie_status, 206647),
  ('The Silence of the Lambs', 'FBI trainee, Clarice Starling ventures into a maximum-security asylum to pick the diseased brain of Hannibal Lecter, a psychiatrist turned homicidal cannibal. Starling needs clues to help her capture a serial killer. but her Faustian relationship with Lecter soon leads to his escape, and now two deranged killers are on the loose.', 'https://image.tmdb.org/t/p/w500/qjAyTj2BSth1EQ89vNfo0JYVPFN.jpg', 119, ARRAY['Crime','Drama','Thriller'], ARRAY['English'], 'UA', 8.1, '1991-02-01', 'now_showing'::public.movie_status, 274),
  ('Star Wars: Episode I - The Phantom Menace', 'Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.', 'https://image.tmdb.org/t/p/w500/n8V09dDc02KsSN6Q4hC2BX6hN8X.jpg', 136, ARRAY['Adventure','Action','Science Fiction'], ARRAY['English'], 'UA', 6.4, '1999-05-19', 'now_showing'::public.movie_status, 1893),
  ('Men in Black', 'Men in Black follows the exploits of agents Kay and Jay, members of a top-secret organization established to monitor and police alien activity on Earth. The two Men in Black find themselves in the middle of the deadly plot by an intergalactic terrorist who has arrived on Earth to assassinate two ambassadors from opposing galaxies. In order to prevent worlds from colliding, the MiB must track down the terrorist and prevent the destruction of Earth. It''s just another typical day for the Men in Black.', 'https://image.tmdb.org/t/p/w500/f24UVKq3UiQWLqGWdqjwkzgB8j8.jpg', 98, ARRAY['Action','Adventure','Comedy','Science Fiction'], ARRAY['English','Español'], 'UA', 6.9, '1997-07-02', 'now_showing'::public.movie_status, 607),
  ('Dawn of the Planet of the Apes', 'A group of scientists in San Francisco struggle to stay alive in the aftermath of a plague that is wiping out humanity, while Caesar tries to maintain dominance over his community of intelligent apes.', 'https://image.tmdb.org/t/p/w500/2EUAUIu5lHFlkj5FRryohlH6CRO.jpg', 130, ARRAY['Science Fiction','Action','Drama','Thriller'], ARRAY['English'], 'UA', 7.3, '2014-06-26', 'now_showing'::public.movie_status, 119450),
  ('The Prestige', 'A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences.', 'https://image.tmdb.org/t/p/w500/5MXyQfz8xUP3dIFPTubhTsbFY6N.jpg', 130, ARRAY['Drama','Mystery','Thriller'], ARRAY['English'], 'UA', 8.0, '2006-10-19', 'now_showing'::public.movie_status, 1124),
  ('Ratatouille', 'A rat named Remy dreams of becoming a great French chef despite his family''s wishes and the obvious problem of being a rat in a decidedly rodent-phobic profession. When fate places Remy in the sewers of Paris, he finds himself ideally situated beneath a restaurant made famous by his culinary hero, Auguste Gusteau. Despite the apparent dangers of being an unlikely - and certainly unwanted - visitor in the kitchen of a fine French restaurant, Remy''s passion for cooking soon sets into motion a hilarious and exciting rat race that turns the culinary world of Paris upside down.', 'https://image.tmdb.org/t/p/w500/jEiEU8viSb8CIIHcfprVr2V6XDz.jpg', 111, ARRAY['Animation','Comedy','Family','Fantasy'], ARRAY['English'], 'UA', 7.5, '2007-06-22', 'now_showing'::public.movie_status, 2062),
  ('Star Trek Into Darkness', 'When the crew of the Enterprise is called back home, they find an unstoppable force of terror from within their own organization has detonated the fleet and everything it stands for, leaving our world in a state of crisis.  With a personal score to settle, Captain Kirk leads a manhunt to a war-zone world to capture a one man weapon of mass destruction. As our heroes are propelled into an epic chess game of life and death, love will be challenged, friendships will be torn apart, and sacrifices must be made for the only family Kirk has left: his crew.', 'https://image.tmdb.org/t/p/w500/41mhrXASAW3sdn7LBWF49uCX0xi.jpg', 132, ARRAY['Action','Adventure','Science Fiction'], ARRAY['English'], 'UA', 7.4, '2013-05-05', 'now_showing'::public.movie_status, 54138),
  ('Split', 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.', 'https://image.tmdb.org/t/p/w500/rXMWOZiCt6eMX22jWuTOSdQ98bY.jpg', 117, ARRAY['Horror','Thriller'], ARRAY['English'], 'UA', 7.0, '2016-11-15', 'now_showing'::public.movie_status, 381288),
  ('The Departed', 'To take down South Boston''s Irish Mafia, the police send in one of their own to infiltrate the underworld, not realizing the syndicate has done likewise. While an undercover cop curries favor with the mob kingpin, a career criminal rises through the police ranks. But both sides soon discover there''s a mole among them.', 'https://image.tmdb.org/t/p/w500/tGLO9zw5ZtCeyyEWgbYGgsFxC6i.jpg', 151, ARRAY['Drama','Thriller','Crime'], ARRAY['English','广州话 / 廣州話'], 'UA', 7.9, '2006-10-05', 'now_showing'::public.movie_status, 1422),
  ('Rise of the Planet of the Apes', 'Scientist Will Rodman is determined to find a cure for Alzheimer''s, the disease which has slowly consumed his father. Will feels certain he is close to a breakthrough and tests his latest serum on apes, noticing dramatic increases in intelligence and brain activity in the primate subjects – especially Caesar, his pet chimpanzee.', 'https://image.tmdb.org/t/p/w500/esqXMJv6PiK7GJVRwd2FA3SZUoW.jpg', 105, ARRAY['Thriller','Action','Drama','Science Fiction'], ARRAY['English'], 'UA', 7.0, '2011-08-03', 'now_showing'::public.movie_status, 61791),
  ('Taken', 'While vacationing with a friend in Paris, an American girl is kidnapped by a gang of human traffickers intent on selling her into forced prostitution. Working against the clock, her ex-spy father must pull out all the stops to save her. But with his best years possibly behind him, the job may be more than he can handle.', 'https://image.tmdb.org/t/p/w500/3zlffXmo7QpVBc17QIJWrRfasVr.jpg', 93, ARRAY['Action','Thriller'], ARRAY['English','Français'], 'UA', 7.2, '2008-02-18', 'now_showing'::public.movie_status, 8681),
  ('Schindler''s List', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', 'https://image.tmdb.org/t/p/w500/yPisjyLweCl1tbgwgtzBCNCBle.jpg', 195, ARRAY['Drama','History','War'], ARRAY['Deutsch','Polski'], 'UA', 8.3, '1993-11-29', 'now_showing'::public.movie_status, 424),
  ('Spider-Man 2', 'Peter Parker is going through a major identity crisis. Burned out from being Spider-Man, he decides to shelve his superhero alter ego, which leaves the city suffering in the wake of carnage left by the evil Doc Ock. In the meantime, Parker still can''t act on his feelings for Mary Jane Watson, a girl he''s loved since childhood.', 'https://image.tmdb.org/t/p/w500/qtBFrsEQ4oXW8sKvRxkKnYuPLg.jpg', 127, ARRAY['Action','Adventure','Fantasy'], ARRAY['English','Pусский'], 'UA', 6.7, '2004-06-25', 'now_showing'::public.movie_status, 558);
